int spng_set_gama(spng_ctx *ctx, double gamma)
{
    if(ctx == NULL) return 1;

    int ret = get_ancillary2(ctx);
    if(ret) return ret;

    uint32_t gama = gamma * 100000.0;

    if(gama > png_u32max) return 1;

    ctx->gama = gama;

    ctx->stored_gama = 1;
    ctx->user_gama = 1;

    return 0;
}
